export interface ICourseQuestionFilterModel {

    title: string;
    questions: IQuestionModel[];
    sortId: number;
    courseId: number;
    isCourseFree: boolean;
    courseName: string;
    isRested: boolean;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;
}

export class CourseQuestionFilterModel implements ICourseQuestionFilterModel {

    title: string;
    questions: IQuestionModel[];
    sortId: number;
    courseId: number;
    isCourseFree: boolean;
    courseName: string;
    isRested: boolean;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;

    constructor(
        courseId: number,
        pageId?: number,
        takeEntity?: number,
        title?: string,
        sortId?: number) {

        if (+takeEntity > 36) {
            this.takeEntity = 36;
        }
        else if (+takeEntity < 1) {
            this.takeEntity = 1;
        }
        else {
            this.takeEntity = takeEntity ? +takeEntity : 12;
        }

        this.pageId = pageId ? +pageId : 1;
        this.title = title ? title : null;
        this.sortId = sortId ? +sortId : 0;
        this.courseId = courseId;
    }
}

